/**
 * The last page you saw, kept for when there is no network.
 *
 * The home screen is a Server Component: without a network there is no
 * document at all, not merely no data. So unlike the mobile client - where
 * persisting the query cache is enough - the thing worth keeping here is the
 * rendered response, and only a service worker sits early enough to hand it
 * back.
 *
 * Deliberately hand-written rather than generated by a plugin. What this does
 * is one strategy on one route; a generated worker would bring precaching of
 * the whole build, a manifest to keep in step, and a much larger surface for
 * the failure mode below.
 *
 * That failure mode, stated plainly: a service worker is durable state in
 * somebody else's browser. Get it wrong and it serves last month's app to a
 * user who cannot clear it, forever. Three things guard against that - the
 * cache name carries a version, activation deletes every cache that is not the
 * current one, and the worker takes over immediately rather than waiting for
 * every tab to close.
 */

// Bump on any change to this file or to what a cached response may contain.
const VERSION = "v1";
const CACHE = `weather-app-${VERSION}`;

/** Marks a response as coming from disk, and says when it was put there. */
const CACHED_AT = "x-cached-at";

self.addEventListener("install", (event) => {
  // No precaching: there is nothing worth storing before the user has seen a
  // page, and precaching a route would store one rendered for nobody - the
  // default location rather than theirs.
  event.waitUntil(self.skipWaiting());
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name !== CACHE).map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Navigations only. API calls are deliberately left alone: a warning served
  // from yesterday's cache would announce a storm that has ended, and offline
  // there is nothing to correct it. The page below carries that risk too,
  // which is why a cached page is served with a timestamp and the app says so.
  if (request.mode !== "navigate" || request.method !== "GET") return;

  event.respondWith(
    (async () => {
      try {
        const response = await fetch(request);

        // Only a real answer is worth keeping. A 500 cached here would outlive
        // the outage that produced it.
        if (response.ok) {
          const cache = await caches.open(CACHE);
          await cache.put(request, stamp(response.clone()));
        }
        return response;
      } catch {
        const cached = await caches.match(request, { ignoreSearch: false });
        if (cached) return cached;

        // Nothing for this URL. Any page we do have is a better answer than
        // the browser's own error, because it at least shows a forecast.
        const cache = await caches.open(CACHE);
        const [fallback] = await cache.keys();
        if (fallback) {
          const response = await cache.match(fallback);
          if (response) return response;
        }

        throw new Error("offline and nothing cached");
      }
    })(),
  );
});

/**
 * Re-wraps a response with the time it was stored.
 *
 * The page reads this back to say how old what it is showing is. Without it an
 * offline visitor sees a forecast with no way to tell whether it is from ten
 * minutes ago or from last week - which is the failure this whole feature
 * invites.
 */
function stamp(response) {
  const headers = new Headers(response.headers);
  headers.set(CACHED_AT, new Date().toISOString());

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}
